const isRussian = document.documentElement.lang === 'ru';
const t = (en, ru) => isRussian ? ru : en;
const reduced = matchMedia('(prefers-reduced-motion: reduce)');
document.querySelector('#year').textContent = new Date().getFullYear();
const menu = document.querySelector('.menu');
menu.addEventListener('click', () => {const open = menu.getAttribute('aria-expanded') !== 'true';menu.setAttribute('aria-expanded', open);menu.setAttribute('aria-label', open ? t('Close menu', 'Закрыть меню') : t('Open menu', 'Открыть меню'));document.querySelector('nav').classList.toggle('open', open);});
document.querySelectorAll('nav a').forEach(a => a.addEventListener('click',()=>{document.querySelector('nav').classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label',t('Open menu', 'Открыть меню'));}));
const reveals = new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');reveals.unobserve(e.target);}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>reveals.observe(el));
const gallery = document.querySelector('#gallery');
document.querySelectorAll('.work').forEach(work=>work.addEventListener('click',()=>{gallery.querySelector('img').src='assets/'+work.dataset.image;gallery.querySelector('img').alt=work.querySelector('img').alt;gallery.querySelector('h3').textContent=work.dataset.title;gallery.showModal();}));
gallery.querySelector('a').addEventListener('click',()=>gallery.close());
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.dialog-close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});});
document.querySelector('#enquiry').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target);document.querySelector('#brief').textContent=`${t('VASH REMONT — PROJECT ENQUIRY', 'ВАШ РЕМОНТ — ЗАЯВКА НА РЕМОНТ')}\n\n${t('Name', 'Имя')}: ${data.get('name')}\n${t('Email', 'Электронная почта')}: ${data.get('email')}\n${t('Service', 'Услуга')}: ${data.get('service')}\n\n${t('Project details', 'Описание проекта')}:\n${data.get('message')}`;document.querySelector('#copy-status').textContent='';document.querySelector('#enquiry-dialog').showModal();});
document.querySelector('#copy-brief').addEventListener('click',async()=>{const text=document.querySelector('#brief').textContent;try{await navigator.clipboard.writeText(text);document.querySelector('#copy-status').textContent=t('Copied. Your brief is ready to share.', 'Скопировано. Заявку можно передать команде.');}catch{const range=document.createRange();range.selectNodeContents(document.querySelector('#brief'));const sel=getSelection();sel.removeAllRanges();sel.addRange(range);document.querySelector('#copy-status').textContent=t('Select and copy the highlighted brief.', 'Скопируйте выделенный текст заявки.');}});

// Scroll is the sole owner of the construction group transforms.
async function createBuilding(){
 const canvas=document.querySelector('#building'),wrap=canvas.parentElement;
 let renderer;
 try{
 const THREE=await import('./vendor/three.module.js');
 renderer=new THREE.WebGLRenderer({canvas,alpha:true,antialias:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setClearColor(0,0);renderer.outputColorSpace=THREE.SRGBColorSpace;
 const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(34,1,.1,100);camera.position.set(10,8,12);camera.lookAt(0,1.5,0);
 scene.add(new THREE.HemisphereLight(0xf4ecd9,0x353b32,2.9));const key=new THREE.DirectionalLight(0xffe3be,4);key.position.set(3,10,7);scene.add(key);const fill=new THREE.DirectionalLight(0xa7bed0,2);fill.position.set(-6,3,-4);scene.add(fill);
 const house=new THREE.Group();scene.add(house);house.rotation.y=-.25;
 const materials={stone:new THREE.MeshStandardMaterial({color:0x72776b,roughness:.9}),wall:new THREE.MeshStandardMaterial({color:0xd6d0bd,roughness:.8}),copper:new THREE.MeshStandardMaterial({color:0xb48660,roughness:.45,metalness:.35}),dark:new THREE.MeshStandardMaterial({color:0x343a32,roughness:.7}),glass:new THREE.MeshStandardMaterial({color:0x89a5a0,metalness:.3,roughness:.15,transparent:true,opacity:.65})};
 const geometries=new Map();const box=(w,h,d)=>{const id=[w,h,d].join('/');if(!geometries.has(id))geometries.set(id,new THREE.BoxGeometry(w,h,d));return geometries.get(id);};
 function block(parent,w,h,d,x,y,z,mat){const mesh=new THREE.Mesh(box(w,h,d),materials[mat]);mesh.position.set(x,y,z);parent.add(mesh);return mesh;}
 const base=new THREE.Group(),walls=new THREE.Group(),roof=new THREE.Group();house.add(base,walls,roof);
 block(base,7.4,.2,6.2,0,-.2,0,'dark');block(base,6.2,.35,4.9,0,.05,0,'stone');block(base,5.8,.18,4.5,0,.32,0,'copper');
 // One instanced mesh for repeated floor boards, another for facade fins.
 const matrix=new THREE.Matrix4();const boards=new THREE.InstancedMesh(box(.28,.05,4.3),materials.wall,19);for(let i=0;i<19;i++){matrix.makeTranslation(-2.7+i*.3,.44,0);boards.setMatrixAt(i,matrix);}boards.instanceMatrix.needsUpdate=true;boards.computeBoundingSphere();base.add(boards);
 block(walls,5.8,2.7,.16,0,1.8,-2.15,'wall');block(walls,.16,2.7,4.4,-2.85,1.8,0,'wall');block(walls,.16,2.7,2,2.85,1.8,-1.2,'wall');block(walls,1.8,2.7,.16,2,1.8,2.15,'wall');
 // Front glazing and exposed interior give the architectural cutaway a readable silhouette.
 block(walls,3.8,2.35,.08,-.9,1.65,2.15,'glass');for(const x of [-2.8,-.9,1])block(walls,.07,2.5,.14,x,1.68,2.2,'dark');block(walls,4,.1,.15,-.9,2.94,2.2,'dark');block(walls,4,.1,.15,-.9,.5,2.2,'dark');
 block(walls,.12,2.2,2.7,.7,1.5,-.72,'wall');block(walls,1.7,.4,.8,-1.6,.76,-1.25,'dark');block(walls,1.7,.6,.18,-1.6,1,-1.6,'copper');block(walls,.9,.15,.6,-1.4,.75,.1,'copper');block(walls,1.5,.25,1.8,1.65,.65,-.8,'wall');block(walls,1.4,.17,.55,1.65,.9,-1.4,'copper');
 const fins=new THREE.InstancedMesh(box(.08,2.7,.12),materials.copper,14);for(let i=0;i<14;i++){matrix.makeTranslation(1.2+i*.12,1.8,2.27);fins.setMatrixAt(i,matrix);}fins.instanceMatrix.needsUpdate=true;fins.computeBoundingSphere();walls.add(fins);
 block(roof,6.25,.2,4.85,0,3.26,0,'dark');block(roof,6.4,.1,5,0,3.42,0,'copper');block(roof,1.4,.4,.8,1.7,3.65,-1,'dark');
 const grid=new THREE.GridHelper(12,24,0x777763,0x474c40);grid.position.y=-.32;scene.add(grid);
 // Deterministic, fixed-capacity architectural dust; no allocations per frame.
 const count=110,positions=new Float32Array(count*3);let seed=42;function random(){seed=(seed*16807)%2147483647;return(seed-1)/2147483646;}for(let i=0;i<count;i++){positions[i*3]=(random()-.5)*13;positions[i*3+1]=random()*7;positions[i*3+2]=(random()-.5)*11;}const dustGeo=new THREE.BufferGeometry();dustGeo.setAttribute('position',new THREE.BufferAttribute(positions,3));const dustMat=new THREE.PointsMaterial({color:0xd3a47b,size:.025,transparent:true,opacity:.45,depthWrite:false});const dust=new THREE.Points(dustGeo,dustMat);scene.add(dust);
 const section=document.querySelector('.build-section'),buttons=[...document.querySelectorAll('[data-step]')],description=document.querySelector('.layer-description');const descriptions=[t('A measured plan, a defined scope, and the right base for everything that follows.', 'Точный план, согласованный объём работ и надёжная основа для следующих этапов.'),t('Careful construction, considered layouts, and the hidden details that make a home work.', 'Аккуратные работы, удобная планировка и скрытые детали, от которых зависит комфорт.'),t('Materials, lighting, and precise finishing bring every part of the plan together.', 'Материалы, освещение и аккуратная отделка объединяют все детали проекта.')];
 let progress=0,active=-1,visible=false,raf=0,last=0,elapsed=0,manual=null,rangeStart=0,rangeLength=1;
 function resize(){const w=wrap.clientWidth,h=wrap.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();rangeStart=section.getBoundingClientRect().top+scrollY;rangeLength=Math.max(1,section.offsetHeight-innerHeight);updateScroll();}
 function updateScroll(){progress=reduced.matches?1:THREE.MathUtils.clamp((scrollY-rangeStart)/rangeLength,0,1);if(manual!==null)progress=manual;draw(performance.now());}
 buttons.forEach((b,i)=>b.addEventListener('click',()=>{if(reduced.matches){manual=i/2;updateScroll();}else{manual=null;window.scrollTo({top:rangeStart+rangeLength*(i/2),behavior:'smooth'});}}));
 function draw(now){const delta=Math.min((now-last)/1000,.05)||0;last=now;if(!reduced.matches)elapsed+=delta;walls.position.y=(1-THREE.MathUtils.smoothstep(progress,0,.6))*2.4;roof.position.y=(1-THREE.MathUtils.smoothstep(progress,.35,1))*4.2;roof.visible=progress>.15;walls.visible=progress>.03||reduced.matches;house.rotation.y=-.5+progress*.7;dust.rotation.y=reduced.matches?0:elapsed*.018;dust.visible=!reduced.matches;const index=progress<.3?0:progress<.72?1:2;if(index!==active){active=index;buttons.forEach((b,i)=>{b.classList.toggle('active',i===index);b.setAttribute('aria-pressed',i===index);});description.textContent=descriptions[index];}renderer.render(scene,camera);}
 function loop(now){raf=0;if(!visible||document.hidden||reduced.matches)return;draw(now);raf=requestAnimationFrame(loop);}
 function start(){if(visible&&!document.hidden&&!reduced.matches&&!raf){last=performance.now();raf=requestAnimationFrame(loop);}else if(raf&&(document.hidden||!visible||reduced.matches)){cancelAnimationFrame(raf);raf=0;}if(visible)updateScroll();}
 const observer=new IntersectionObserver(([entry])=>{visible=entry.isIntersecting;start();},{rootMargin:'100px'});observer.observe(wrap);const resizeObserver=new ResizeObserver(resize);resizeObserver.observe(wrap);window.addEventListener('scroll',()=>{if(visible){manual=null;updateScroll();}},{passive:true});document.addEventListener('visibilitychange',start);reduced.addEventListener('change',()=>{manual=null;resize();start();});resize();
 canvas.addEventListener('webglcontextlost',event=>{event.preventDefault();cancelAnimationFrame(raf);canvas.hidden=true;wrap.querySelector('.model-fallback').hidden=false;});
 window.addEventListener('pagehide',()=>{cancelAnimationFrame(raf);observer.disconnect();resizeObserver.disconnect();for(const geo of geometries.values())geo.dispose();Object.values(materials).forEach(m=>m.dispose());dustGeo.dispose();dustMat.dispose();grid.geometry.dispose();grid.material.dispose();renderer.dispose();},{once:true});
 }catch(error){console.warn('3D preview unavailable; showing construction stages.',error);canvas.hidden=true;wrap.querySelector('.model-fallback').hidden=false;document.querySelector('.model-note').hidden=true;document.querySelectorAll('[data-step]').forEach((b,i)=>b.addEventListener('click',()=>{document.querySelectorAll('[data-step]').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelector('.layer-description').textContent=[t('A measured plan and a solid foundation.', 'Точный план и надёжная основа.'),t('Careful structure and considered layouts.', 'Надёжные конструкции и продуманная планировка.'),t('Materials, lighting, and precise finishing.', 'Материалы, освещение и аккуратная отделка.')][i];}));renderer?.dispose();}
}
createBuilding();
